        [Fact(DisplayName = "alerts > worst first: zombies, fire and the infected before hunger and visitors")]
        public void T002_worst_first_zombies_fire_and_the_infected_before_hunger_and_()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.b......", "........."] });
            var s = Js.NN(Js.Get(state.survivors, 0));
            s.infection = 10;
            s.satiety = 100;
            Zombies.addZombie(state, 6, 1, 200, "static");
            FireMod.ignite(state, 8, 0);
            var list = Alerts.alerts(state);
            var levels = list.map((a) => a.level);
            expect(levels).toEqual(Js.ListOf(levels).sort((a, b) => new List<string> { "danger", "warn", "info" }.indexOf(a) - new List<string> { "danger", "warn", "info" }.indexOf(b)));
            expect(list.filter((a) => a.level == "danger").map((a) => a.text)).toEqual(Js.Arr(["1 zombie near the colony", "Fire! 1 tile burning", Vitest.stringMatching(new JsRegExp("^Ash is infected", "")), "Food for less than a day (1 to feed)"]));
            expect(list.some((a) => a.text == "Ash is hungry")).toBe(true);
        }

        [Fact(DisplayName = "alerts > warns about winter when the food will not last it")]
        public void T003_warns_about_winter_when_the_food_will_not_last_it()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["ssb.ffffff"] });
            state.tick = Js.I(((2 * Seasons.SEASON_DAYS) + 2) * Time.DAY_LENGTH);
            expect(Alerts.daysToWinter(state.tick)).toBe(3);
            expect(Alerts.foodDays(state)).toBeLessThan(Seasons.SEASON_DAYS);
            expect(Alerts.alerts(state).some((a) => a.text.startsWith("Winter in 3 days"))).toBe(true);
        }

        [Fact(DisplayName = "alerts > never changes state")]
        public void T004_never_changes_state()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.ffw", "....."] });
            state.harsh = true;
            var before = Js.Json_stringify(States.cloneState(state));
            Alerts.alerts(state);
            Alerts.stockCounts(state);
            expect(Js.Json_stringify(state)).toBe(before);
            expect(Alerts.stockCounts(state)).toEqual(Js.Arr([Js.Arr(["food", 2]), Js.Arr(["wood", 1])]));
        }
    }
